class Temperature {
  private _celsius = 0;
  get celsius(): number { return this._celsius; }
  set celsius(value: number) {
    if (value < -273.15) throw new Error('below absolute zero');
    this._celsius = value;
  }
}

const temp = new Temperature();
temp.celsius = 25;
console.log(temp.celsius);

