solution.code:
class User {
  constructor(public readonly id: string, public name: string) {}
  withId(newId: string): User {
    return new User(newId, this.name); // new instance, no mutation
  }
}

const u = new User('u1', 'Ada');
const u2 = u.withId('u2');
console.log(u.id, u2.id);

class Stack<T> {
  private items: T[] = [];
  push(item: T): void { this.items.push(item); }
  pop(): T | undefined { return this.items.pop(); }
  get size(): number { return this.items.length; }
  static from<U>(arr: U[]): Stack<U> {
    const s = new Stack<U>();
    for (const x of arr) s.push(x);
    return s;
  }
}

const s = Stack.from([1, 2, 3]);
console.log(s.size, s.pop());
